UPDATE dispatch
SET status = 'PENDING',
    executor_id = NULL,
    package_oss_ref = NULL,
    version = version + 1,
    modifier_id = #{modifierId}
WHERE id = #{id}
  AND tenant_id = #{tenantId}
  AND executor_id = #{executorId}
  AND status = 'DISPATCHED'
  AND version = #{version}
  AND is_deleted = 0

UPDATE dispatch
SET status = 'PENDING',
    agent_version_id = NULL,
    executor_id = NULL,
    package_oss_ref = NULL,
    version = version + 1,
    modifier_id = #{modifierId}
WHERE id = #{id}
  AND tenant_id = #{tenantId}
  AND status = 'PACKAGING'
  AND version = #{version}
  AND is_deleted = 0

UPDATE dispatch
SET status = 'PENDING',
    agent_version_id = NULL,
    executor_id = NULL,
    package_oss_ref = NULL,
    result_summary = NULL,
    error = NULL,
    version = version + 1,
    modifier_id = #{modifierId}
WHERE id = #{id}
  AND tenant_id = #{tenantId}
  AND executor_id = #{executorId}
  AND status IN ('DISPATCHED', 'ACKED', 'RUNNING')
  AND version = #{version}
  AND is_deleted = 0

UPDATE dispatch
SET gmt_modified = NOW()
WHERE tenant_id = #{tenantId}
  AND executor_id = #{executorId}
  AND status IN ('PACKAGING', 'DISPATCHED', 'ACKED', 'RUNNING')
  AND is_deleted = 0
  AND id IN
  #{id}

UPDATE dispatch
SET status = 'PAUSE_FAILED',
    error = #{error},
    version = version + 1,
    modifier_id = #{modifierId}
WHERE id = #{id}
  AND tenant_id = #{tenantId}
  AND status = 'PAUSING'
  AND gmt_modified < FROM_UNIXTIME(#{beforeEpochMillis} / 1000)
  AND is_deleted = 0

UPDATE dispatch
SET gmt_modified = NOW()
WHERE id = #{id}
  AND tenant_id = #{tenantId}
  AND executor_id = #{executorId}
  AND status IN ('DISPATCHED', 'ACKED', 'RUNNING')
  AND is_deleted = 0
